package com.tekwatt.tariff.controller;import com.tekwatt.tariff.dto.*;import com.tekwatt.tariff.service.TariffService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/tariffs") public class TariffController {private final TariffService service;public TariffController(TariffService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED)TariffResponse create(@Valid @RequestBody TariffRequest r){return service.create(r);}@GetMapping("/{id}")TariffResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping List<TariffResponse> list(@RequestParam UUID tenantId){return service.list(tenantId);}@PutMapping("/{id}")TariffResponse update(@PathVariable UUID id,@Valid @RequestBody TariffRequest r){return service.update(id,r);}@PatchMapping("/{id}/status")TariffResponse status(@PathVariable UUID id,@Valid @RequestBody TariffStatusRequest r){return service.status(id,r);}}
